import numpy as np
from scipy.optimize import brentq

ligands = {
    'Glycine': {
        'pKa': [2.35, 9.78],
        'metals': {'Cu':[8.15,15.03], 'Ni':[5.72,10.61,13.83], 'Co':[4.60,8.35,10.72]}
    },
    'L-Histidine': {
        'pKa': [1.70, 6.04, 9.09],
        'metals': {'Cu':[10.20,18.20], 'Ni':[8.69,15.53], 'Co':[6.87,12.24]}
    },
    'L-Aspartate': {
        'pKa': [2.05, 3.87, 9.82],
        'metals': {'Cu':[8.57,14.78], 'Ni':[7.12,12.42], 'Co':[5.90,10.13]}
    },
}
hydrolysis = {'Cu':[6.3,11.8,14.5,15.6], 'Ni':[4.1,8.0,11.0,12.0], 'Co':[4.3,8.4,9.7,10.2]}

def alpha_L(pH, pKas):
    H = 10**(-pH)
    pk = sorted(pKas)
    a = 1.0
    for i in range(len(pk)):
        a += 10**(sum(pk[-(j+1)] for j in range(i+1))) * H**(i+1)
    return a

def alpha_M(pH, lb):
    OH = 10**(pH-14); a = 1.0
    for i,b in enumerate(lb): a += 10**b * OH**(i+1)
    return a

def speciate(M_T, L_T, pH, ligand_name, metal):
    d = ligands[ligand_name]; betas = d['metals'][metal]
    aL = alpha_L(pH, d['pKa']); aM = alpha_M(pH, hydrolysis[metal])

    def M_of_L(L):
        S1 = sum(10**betas[i]*L**(i+1) for i in range(len(betas)))
        return M_T / (aM + S1)

    def L_balance(L):
        M = M_of_L(L)
        S2 = sum((i+1)*10**betas[i]*L**(i+1) for i in range(len(betas)))
        return L*aL + M*S2 - L_T

    # L must lie between ~0 and L_T/aL. Bracket in log-space.
    L = brentq(L_balance, 1e-30, L_T/aL*1.0001, xtol=1e-25, rtol=1e-12)
    M = M_of_L(L)

    sp = {'M2+': M, 'ML': 10**betas[0]*M*L}
    if len(betas) >= 2: sp['ML2'] = 10**betas[1]*M*L**2
    if len(betas) >= 3: sp['ML3'] = 10**betas[2]*M*L**3
    sp['M(OH)+']  = 10**hydrolysis[metal][0]*M*10**(pH-14)
    sp['M(OH)2']  = 10**hydrolysis[metal][1]*M*10**(2*(pH-14))
    return M, L, sp

pH = 7.0; M_T, L_T = 1e-3, 5e-3
print(f"Speciation at pH {pH}, [M]_T=1 mM, [L]_T=5 mM, I=0.1 M\n")
print(f"{'Ligand':<14}{'M':<4}{'pM':>7}{'pL(free)':>10}{'%ML':>7}{'%ML2':>7}{'%ML3':>7}{'%M2+':>8}{'%hydr':>8}")
results = {}
for lig in ligands:
    for met in ['Cu','Ni','Co']:
        M,L,sp = speciate(M_T,L_T,pH,lig,met)
        pM = -np.log10(M); pL = -np.log10(L)
        pct = {k: 100*v/M_T for k,v in sp.items()}
        print(f"{lig:<14}{met:<4}{pM:>7.2f}{pL:>10.2f}"
              f"{pct['ML']:>7.1f}{pct.get('ML2',0):>7.1f}{pct.get('ML3',0):>7.1f}"
              f"{pct['M2+']:>8.2e}{pct['M(OH)+']+pct['M(OH)2']:>8.2e}")
        results.setdefault(lig,{})[met] = pM
    print()

print("Discrimination (Δ pM = log10 ratio of free [M2+]):")
print(f"{'Ligand':<14}{'pCu-pCo':>9}{'pCu-pNi':>9}{'pNi-pCo':>9}{'range':>8}")
for lig,r in results.items():
    print(f"{lig:<14}{r['Cu']-r['Co']:>9.2f}{r['Cu']-r['Ni']:>9.2f}"
          f"{r['Ni']-r['Co']:>9.2f}{max(r.values())-min(r.values()):>8.2f}")

print("\npH sensitivity of L-Histidine (Δ pM range):")
print(f"{'pH':<5}{'pCu':>7}{'pNi':>7}{'pCo':>7}{'range':>8}")
for pH in [6.0,6.5,7.0,7.5,8.0]:
    row = {}
    for met in ['Cu','Ni','Co']:
        M,_,_ = speciate(M_T,L_T,pH,'L-Histidine',met); row[met]=-np.log10(M)
    print(f"{pH:<5}{row['Cu']:>7.2f}{row['Ni']:>7.2f}{row['Co']:>7.2f}"
          f"{max(row.values())-min(row.values()):>8.2f}")

print("\npH sensitivity of Glycine (for comparison):")
print(f"{'pH':<5}{'pCu':>7}{'pNi':>7}{'pCo':>7}{'range':>8}")
for pH in [6.0,6.5,7.0,7.5,8.0]:
    row = {}
    for met in ['Cu','Ni','Co']:
        M,_,_ = speciate(M_T,L_T,pH,'Glycine',met); row[met]=-np.log10(M)
    print(f"{pH:<5}{row['Cu']:>7.2f}{row['Ni']:>7.2f}{row['Co']:>7.2f}"
          f"{max(row.values())-min(row.values()):>8.2f}")
