from speciation import solve_point
# quick sanity checks
for pH in [3, 5, 7, 9]:
    for E in [-0.2, 0.4, 0.8]:
        r = solve_point(pH, E)
        # find largest species in each block
        def top(d): return max(d.items(), key=lambda kv: kv[1])
        print(f'pH={pH}  E={E:+.2f} V  |  Fe(III):{top(r[\"Fe3_species\"])}  Fe(II):{top(r[\"Fe2_species\"])}  Cu(II):{top(r[\"Cu2_species\"])}  Cu(I):{top(r[\"Cu1_species\"])}  solids={ {k:v for k,v in r[\"solids\"].items() if v} }')
"

