# Build the HTML report as a single self-contained file
import base64, json, os

def read(p):
    with open(p) as f:
        return f.read()

def b64png(p):
    with open(p, "rb") as f:
        return base64.b64encode(f.read()).decode()

def svg_body(p):
    """Return the SVG stripped of XML/DOCTYPE headers so it inlines cleanly."""
    s = read(p)
    # drop everything before the first <svg tag
    i = s.find("<svg")
    return s[i:]

