cit_mid  = svg_body("figs/citrate_partition_mid.svg")

summary = json.loads(read("figs/summary.json"))
cit_table = json.loads(read("figs/citrate_table.json"))

# Format summary rows
def fmt_pct(v):
    if v >= 1: return f"{v:.1f}%"
    if v >= 0.1: return f"{v:.2f}%"
    return "<0.1%"

def row_summary(r):
    fe = ", ".join(f"<b>{s}</b>&nbsp;{fmt_pct(f*100)}" for s, f in r['Fe_top'] if f > 0.001)
    cu = ", ".join(f"<b>{s}</b>&nbsp;{fmt_pct(f*100)}" for s, f in r['Cu_top'] if f > 0.001)
    if not fe: fe = "<span class='muted'>&mdash; (all Fe(OH)<sub>3</sub>(s))</span>"
    if not cu: cu = "<span class='muted'>&mdash; (all Cu(OH)<sub>2</sub>(s))</span>"
    solids = ", ".join(r['solids']) if r['solids'] else "<span class='muted'>&mdash;</span>"
    return f"<tr><td class='n'>{r['pH']:.1f}</td><td>{fe}</td><td>{cu}</td><td>{solids}</td></tr>"

summary_rows = "\n".join(row_summary(r) for r in summary)

def row_cit(r):
    return (f"<tr><td class='n'>{r['pH']}</td>"
            f"<td class='n'>{r['free_pct']:.1f}</td>"
            f"<td class='n'>{r['Fe_pct']:.1f}</td>"
            f"<td class='n'>{r['Cu_pct']:.1f}</td></tr>")

