<tr><td class="rxn">Fe<sup>2+</sup> + H<sub>2</sub>O &rlarr; FeOH<sup>+</sup> + H<sup>+</sup></td><td class="n">log *K = &minus;9.5</td><td>Baes &amp; Mesmer 1976</td></tr>
