            j = i+1
            if j < len(s) and s[j] == '(':
                k = s.index(')', j); tok = s[j+1:k]; i = k+1
            else:
                tok = ''
                while j < len(s) and (s[j].isdigit() or s[j] in '+-'): tok += s[j]; j += 1
                i = j
            dy = '0.32em' if c == '_' else '-0.45em'
            back = '-0.32em' if c == '_' else '0.45em'
            out += f'<tspan dy="{dy}" font-size="{int(size*0.72)}">{tok}</tspan><tspan dy="{back}"> </tspan>'.replace('> </tspan>', '></tspan>')
        else:
            out += c; i += 1
    return out
